
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_m06_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_m06_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.047842914948156e+00, -4.921041988561429e+00, -4.742628423488613e+00, -4.498585023330831e+00, -4.182678211216974e+00, -3.809140539035305e+00, -3.394581501210812e+00, -2.845785745234767e+00, -2.131727513330570e+00, -1.477822485615796e+00, -9.013564887803572e-01, -6.001279239617970e-01, -6.333233470461195e-01, -5.265706195143246e-01, -3.541845019978548e-01, -2.124885564732440e-01, -1.838988643959339e-01, -1.848190774969484e-01, -4.768564229708912e-02, -5.410014579859270e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


